#!/usr/bin/env node
// Flags prose in README.md and docs/**/*.md that reads like an AI wrote it.
//
// Usage: node scripts/lint-prose.mjs [file ...]
// With no arguments it checks README.md and every Markdown file under docs/.
//
// Strong patterns fail on one sighting. Weak patterns (single stock words,
// dashes) only fail when two or more land in the same paragraph, because a
// careful human writer uses any one of them now and then.
//
// The checker ignores code blocks, inline code, link targets, and quoted
// text, so a page can quote or discuss a phrase without failing. English
// rules are skipped for pages in another language (docs/de/, docs/fr/, or
// `lang:` front matter), since French dialogue dashes and German
// „…“ – … typography are correct there.

import { readFileSync, readdirSync, statSync, existsSync } from "node:fs";
import { join, relative, sep } from "node:path";

const STRONG = [
  // Chatbot residue
  [/\blet me know if\b/i, "chatbot closer"],
  [/\bi hope this helps\b/i, "chatbot closer"],
  [/\bgreat question\b/i, "chatbot opener"],
  [/\b(certainly|of course|absolutely)!/i, "chatbot opener"],
  [/\byou'?re absolutely right\b/i, "chatbot reply"],
  [/\b(would you like me to|want me to|should i continue)\b/i, "chatbot offer"],
  [/\bas an ai\b|\bmy (last )?training (data|update|cutoff)\b/i, "knowledge-limit disclaimer"],
  // Staged run-ups and closers
  [/\blet'?s (dive|delve) in(to)?\b|\blet'?s (explore|break (this|it) down)\b/i, "staged run-up"],
  [/\bhere'?s (what you need to know|the thing)\b|\bwithout further ado\b/i, "staged run-up"],
  [/\b(that is|that's) the real win\b|\blet that sink in\b|\bread that again\b/i, "dramatic closer"],
  // Inflated significance
  [/\bin today'?s (fast[- ]paced|digital|modern|ever[- ]changing) world\b/i, "inflated opener"],
  [/\b(stands as|is|serves as) a testament to\b/i, "inflated significance"],
  [/\bthe future (of [\w ]+ )?looks bright\b|\bexciting times (lie )?ahead\b/i, "send-off"],
  [/\b(ever[- ])?evolving landscape\b|\bindelible mark\b|\brich tapestry\b/i, "inflated significance"],
  [/\bplays? a (key|pivotal|crucial|vital) role\b/i, "inflated significance"],
  // Not X but Y
  [/\bnot (just|only|merely) [^.;:!?]{1,60}?\bbut\b/i, "not-X-but-Y contrast"],
  [/\bit'?s not (just )?[^.;:!?]{1,40}, it'?s\b/i, "not-X-but-Y contrast"],
];

const WEAK = [
  [/\b(delve[sd]?|delving)\b/i, "stock AI word"],
  [/\b(tapestry|testament|pivotal|seamless(ly)?|showcas(e|es|ed|ing)|underscor(e|es|ed|ing))\b/i, "stock AI word"],
  [/\b(robust|crucial|meticulous(ly)?|vibrant|intricate|intricacies|interplay|garner(ed|s)?|bolster(ed|s)?)\b/i, "stock AI word"],
  [/\b(additionally|landscape|enhance[sd]?|leverag(e|es|ed|ing))\b/i, "stock AI word"],
  [/\b(nestled|breathtaking|groundbreaking|renowned|must-visit|stunning|in the heart of)\b/i, "sales language"],
  [/\b(serves|stands|functions) as\b|\bboasts\b/i, "avoids is/has"],
  [/^\s*[-*+]\s+\*\*[^*]+:\*\*/, "bold list label"],
  // An em dash, or an en dash that is not a numeric range like 1.0–1.2.
  [/—|(?<![\d.])\s*–\s*(?![\d])|\s--\s/, "dash as connector"],
];

const LANG_DIRS = /^(?!en$)[a-z]{2}(-[a-z]{2})?$/i;

function listFiles(root) {
  const files = [];
  if (existsSync(join(root, "README.md"))) files.push(join(root, "README.md"));
  const walk = (dir) => {
    for (const name of readdirSync(dir)) {
      const p = join(dir, name);
      if (statSync(p).isDirectory()) walk(p);
      else if (name.endsWith(".md")) files.push(p);
    }
  };
  if (existsSync(join(root, "docs"))) walk(join(root, "docs"));
  return files;
}

function blank(s) {
  return s.replace(/[^\n]/g, " ");
}

// Returns the file's lines with everything that is not the author's own
// prose replaced by spaces, so line and column numbers stay correct.
function prose(text) {
  let lang = null;
  const fm = text.match(/^---\n([\s\S]*?)\n---\n/);
  if (fm) {
    lang = fm[1].match(/^lang:\s*([\w-]+)/m)?.[1] ?? null;
    text = blank(fm[0]) + text.slice(fm[0].length);
  }
  text = text
    .replace(/<!--[\s\S]*?-->/g, blank)
    .replace(/^ {0,3}(```|~~~)[^\n]*\n[\s\S]*?^ {0,3}\1[^\n]*$/gm, blank);
  const lines = text.split("\n").map((line) =>
    line
      .replace(/^( {4}|\t).*/, blank) // indented code
      .replace(/(`+)[^`]*?\1/g, blank)
      .replace(/\]\([^)]*\)/g, (m) => "]" + blank(m.slice(1)))
      .replace(/<[^>\s]+>|https?:\/\/\S+/g, blank)
      .replace(/"[^"]*"|“[^”]*”|„[^“”]*[“”]|«[^»]*»|‚[^‘]*‘/g, blank)
  );
  return { lines, lang };
}

function lintFile(file, root) {
  const rel = relative(root, file);
  const { lines, lang } = prose(readFileSync(file, "utf8"));
  const dirLang = rel.split(sep).slice(0, -1).find((seg) => LANG_DIRS.test(seg));
  if ((lang && !/^en\b/i.test(lang)) || (!lang && dirLang)) return [];

  const problems = [];
  let weak = [];
  const flush = () => {
    if (weak.length >= 2) problems.push(...weak);
    weak = [];
  };
  lines.forEach((line, i) => {
    if (!line.trim()) return flush();
    for (const [re, why] of STRONG) {
      const m = line.match(re);
      if (m) problems.push({ file: rel, line: i + 1, col: m.index + 1, why, text: m[0] });
    }
    for (const [re, why] of WEAK) {
      const m = line.match(re);
      if (m) weak.push({ file: rel, line: i + 1, col: m.index + 1, why, text: m[0].trim() });
    }
  });
  flush();
  return problems.sort((a, b) => a.line - b.line || a.col - b.col);
}

const root = process.cwd();
const files = process.argv.length > 2 ? process.argv.slice(2).map((f) => join(root, f)) : listFiles(root);
const problems = files.flatMap((f) => lintFile(f, root));

for (const p of problems) {
  const msg = `${p.why}: "${p.text}"`;
  if (process.env.GITHUB_ACTIONS) console.log(`::error file=${p.file},line=${p.line},col=${p.col}::${msg}`);
  console.log(`${p.file}:${p.line}:${p.col}  ${msg}`);
}
if (problems.length) {
  console.log(`\n${problems.length} problem(s) in ${new Set(problems.map((p) => p.file)).size} file(s).`);
  process.exit(1);
}
console.log(`Checked ${files.length} file(s); no AI writing patterns found.`);

